jzModule.SimpleTextModule.initSimpleTextLazyLoad( {"fontList":[{"id":"957099327226","fontId":184,"fontFamily":"fontface__思源黑体Regular__184__957099327226","substring":"智能盲板管理系统是运用GIS地信息、传感单元电子标签等技术，对进行可视化监控和抽堵作业过程的。通以更加精准追踪使情况预防潜在安全风险并优资源配置工石油天然气中广泛应于提升生产具有重要毒害易燃爆介质种类繁多装因方案不合位错误漏拆顺序变形失效而引发串料开停车败火灾炸人身伤亡事故常水平企\u201C夯实三基\u201D一项内容","resId":"_JZFontFace_ABUIg8COEBBMGAAgkdyAyQYouIb4iwM","resUrl":"//33792003.s21i.faiusr.com/76/ABUIg8COEBBMGAAgkdyAyQYouIb4iwM.ttf"}],"isExecInitSimpleText":false,"initSimpleTextData":{},"writingMode":0,"moduleId":919});jzModule.Module.install({"id":919,"type":1,"style":86,"module":{"id":919,"commProp":{"al":[{"t":1,"s":1.0,"d":0.0,"c":1},{"t":0,"s":1.0,"d":0.0,"c":-1}],"cal":[]},"style":86,"flag":7,"prop0":0},"perform":{"moduleAttr":{"_banId":"ABUIABAEGAAg_t-LyAYo14Gj7gYwgA842AQ","_sys":1,"_autoHeight":0}}});

